#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

static int hex4(const string &r, size_t i) { return stoi(r.substr(i, 4), nullptr, 16); }

// Parse a JSON string body starting after the opening quote into code points
// (escaped surrogate pairs combine, as Python's json does).
static vector<int> parseString(const string &r, size_t &i) {
    vector<int> out;
    while (i < r.size() && r[i] != '"') {
        unsigned char c = r[i];
        if (c == '\\') {
            char e = r[i + 1];
            i += 2;
            if (e == 'u') {
                int u = hex4(r, i);
                i += 4;
                if (u >= 0xD800 && u <= 0xDBFF && i + 5 < r.size() && r[i] == '\\' && r[i + 1] == 'u') {
                    int v = hex4(r, i + 2);
                    if (v >= 0xDC00 && v <= 0xDFFF) {
                        u = 0x10000 + ((u - 0xD800) << 10) + (v - 0xDC00);
                        i += 6;
                    }
                }
                out.push_back(u);
            } else {
                out.push_back(e == 'n' ? '\n' : e == 't' ? '\t' : e == 'r' ? '\r' : e == 'b' ? '\b' : e == 'f' ? '\f' : e);
            }
        } else {
            int len = c < 0x80 ? 1 : c < 0xE0 ? 2 : c < 0xF0 ? 3 : 4;
            int cp = len == 1 ? c : c & (0xFF >> (len + 1));
            for (int k = 1; k < len; k++) cp = cp << 6 | (r[i + k] & 0x3F);
            out.push_back(cp);
            i += len;
        }
    }
    i++;
    return out;
}

static ll nextNumber(const string &r, size_t &i) {
    while (i < r.size() && (r[i] == ',' || isspace((unsigned char)r[i]))) i++;
    size_t used;
    ll v = stoll(r.substr(i, 32), &used);
    i += used;
    return v;
}

int main() {
    string r((istreambuf_iterator<char>(cin)), istreambuf_iterator<char>());
    size_t i = r.find('"') + 1;
    vector<int> s = parseString(r, i);
    ll L = nextNumber(r, i);
    nextNumber(r, i);  // maxLength: the shortest allowed length is always optimal
    ll U = nextNumber(r, i);
    int n = s.size();

    // Suffix automaton; occ counts end positions, first is the end index of the first occurrence.
    int maxS = 2 * n + 2;
    vector<map<int, int>> nx(maxS);
    vector<int> link(maxS, -1), len(maxS, 0), first(maxS, -1);
    vector<ll> occ(maxS, 0);
    int sz = 1, last = 0;
    for (int index = 0; index < n; index++) {
        int c = s[index], cur = sz++;
        len[cur] = len[last] + 1, link[cur] = 0, occ[cur] = 1, first[cur] = index;
        int p = last;
        while (p >= 0 && !nx[p].count(c)) nx[p][c] = cur, p = link[p];
        if (p >= 0) {
            int q = nx[p][c];
            if (len[p] + 1 == len[q]) link[cur] = q;
            else {
                int clone = sz++;
                nx[clone] = nx[q];
                len[clone] = len[p] + 1, link[clone] = link[q], occ[clone] = 0, first[clone] = first[q];
                while (p >= 0 && nx[p][c] == q) nx[p][c] = clone, p = link[p];
                link[q] = link[cur] = clone;
            }
        }
        last = cur;
    }
    // States by length descending (counting sort), then push counts up suffix links.
    vector<int> bucket(n + 2, 0), order(sz - 1);
    for (int v = 1; v < sz; v++) bucket[len[v]]++;
    for (int l = n - 1; l >= 0; l--) bucket[l] += bucket[l + 1];
    for (int v = 1; v < sz; v++) order[--bucket[len[v]]] = v;
    for (int v : order) occ[link[v]] += occ[v];

    // valid[i]: the length-L window ending at i has at most U distinct characters.
    vector<int> cnt(0x110000, 0);
    vector<char> valid(n, 0);
    int distinct = 0;
    for (int k = 0; k < n; k++) {
        if (cnt[s[k]]++ == 0) distinct++;
        if (k >= L && --cnt[s[k - L]] == 0) distinct--;
        if (k >= L - 1) valid[k] = distinct <= U;
    }
    ll best = 0;
    for (int v : order)
        if (len[link[v]] < L && L <= len[v] && valid[first[v]]) best = max(best, occ[v]);
    printf("%lld\n", best);
}

import java.io.*;

public class Main {
    static byte[] r;
    static int pos;

    static int hex4(int i) {
        return Integer.parseInt(new String(r, i, 4), 16);
    }

    // Parse a JSON string body starting after the opening quote into code points
    // (escaped surrogate pairs combine, as Python's json does).
    static int[] parseString() {
        int[] out = new int[r.length];
        int m = 0;
        while (pos < r.length && r[pos] != '"') {
            int c = r[pos] & 0xFF;
            if (c == '\\') {
                char e = (char) r[pos + 1];
                pos += 2;
                if (e == 'u') {
                    int u = hex4(pos);
                    pos += 4;
                    if (u >= 0xD800 && u <= 0xDBFF && pos + 5 < r.length && r[pos] == '\\' && r[pos + 1] == 'u') {
                        int v = hex4(pos + 2);
                        if (v >= 0xDC00 && v <= 0xDFFF) {
                            u = 0x10000 + ((u - 0xD800) << 10) + (v - 0xDC00);
                            pos += 6;
                        }
                    }
                    out[m++] = u;
                } else {
                    out[m++] = e == 'n' ? '\n' : e == 't' ? '\t' : e == 'r' ? '\r' : e == 'b' ? '\b' : e == 'f' ? '\f' : e;
                }
            } else {
                int len = c < 0x80 ? 1 : c < 0xE0 ? 2 : c < 0xF0 ? 3 : 4;
                int cp = len == 1 ? c : c & (0xFF >> (len + 1));
                for (int k = 1; k < len; k++) cp = cp << 6 | (r[pos + k] & 0x3F);
                out[m++] = cp;
                pos += len;
            }
        }
        pos++;
        return java.util.Arrays.copyOf(out, m);
    }

    static long nextNumber() {
        while (pos < r.length && (r[pos] == ',' || r[pos] <= ' ')) pos++;
        boolean neg = r[pos] == '-';
        if (neg) pos++;
        long v = 0;
        while (pos < r.length && r[pos] >= '0' && r[pos] <= '9') v = v * 10 + (r[pos++] - '0');
        return neg ? -v : v;
    }

    // Transitions: a global open-addressing hash (state, char) -> edge id, plus per-state edge lists.
    static long[] hk;
    static int[] hv;
    static int hmask;
    static int[] head, enext, ech, eto;
    static int ecnt;

    static int slot(long key) {
        int i = (int) ((key * 0x9E3779B97F4A7C15L) >>> 32) & hmask;
        while (hk[i] != -1 && hk[i] != key) i = (i + 1) & hmask;
        return i;
    }

    static int edge(int st, int c) {
        int i = slot((long) st << 21 | c);
        return hk[i] == -1 ? -1 : hv[i];
    }

    static void addEdge(int st, int c, int to) {
        ech[ecnt] = c;
        eto[ecnt] = to;
        enext[ecnt] = head[st];
        head[st] = ecnt;
        long key = (long) st << 21 | c;
        int i = slot(key);
        hk[i] = key;
        hv[i] = ecnt++;
    }

    public static void main(String[] args) throws IOException {
        r = System.in.readAllBytes();
        while (r[pos] != '"') pos++;
        pos++;
        int[] s = parseString();
        long L = nextNumber();
        nextNumber(); // maxLength: the shortest allowed length is always optimal
        long U = nextNumber();
        int n = s.length;

        int maxS = 2 * n + 2, maxE = 3 * n + 10;
        int cap = 1;
        while (cap < 2 * maxE) cap <<= 1;
        hk = new long[cap];
        java.util.Arrays.fill(hk, -1);
        hv = new int[cap];
        hmask = cap - 1;
        head = new int[maxS];
        java.util.Arrays.fill(head, -1);
        enext = new int[maxE];
        ech = new int[maxE];
        eto = new int[maxE];
        // Suffix automaton; occ counts end positions, first is the end index of the first occurrence.
        int[] link = new int[maxS], len = new int[maxS], first = new int[maxS];
        long[] occ = new long[maxS];
        link[0] = -1;
        first[0] = -1;
        int sz = 1, last = 0;
        for (int index = 0; index < n; index++) {
            int c = s[index], cur = sz++;
            len[cur] = len[last] + 1;
            occ[cur] = 1;
            first[cur] = index;
            int p = last;
            while (p >= 0 && edge(p, c) < 0) {
                addEdge(p, c, cur);
                p = link[p];
            }
            if (p >= 0) {
                int q = eto[edge(p, c)];
                if (len[p] + 1 == len[q]) link[cur] = q;
                else {
                    int clone = sz++;
                    len[clone] = len[p] + 1;
                    link[clone] = link[q];
                    first[clone] = first[q];
                    for (int e = head[q]; e >= 0; e = enext[e]) addEdge(clone, ech[e], eto[e]);
                    int e;
                    while (p >= 0 && eto[e = edge(p, c)] == q) {
                        eto[e] = clone;
                        p = link[p];
                    }
                    link[q] = link[cur] = clone;
                }
            }
            last = cur;
        }
        // States by length descending (counting sort), then push counts up suffix links.
        int[] bucket = new int[n + 2], order = new int[sz - 1];
        for (int v = 1; v < sz; v++) bucket[len[v]]++;
        for (int l = n - 1; l >= 0; l--) bucket[l] += bucket[l + 1];
        for (int v = 1; v < sz; v++) order[--bucket[len[v]]] = v;
        for (int v : order) occ[link[v]] += occ[v];

        // valid[i]: the length-L window ending at i has at most U distinct characters.
        int[] cnt = new int[0x110000];
        boolean[] valid = new boolean[n];
        int distinct = 0;
        for (int k = 0; k < n; k++) {
            if (cnt[s[k]]++ == 0) distinct++;
            if (k >= L && --cnt[s[(int) (k - L)]] == 0) distinct--;
            if (k >= L - 1) valid[k] = distinct <= U;
        }
        long best = 0;
        for (int v : order)
            if (len[link[v]] < L && L <= len[v] && valid[first[v]]) best = Math.max(best, occ[v]);
        System.out.println(best);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"strconv"
)

var r []byte
var p int

func hex4(i int) int {
	v, _ := strconv.ParseInt(string(r[i:i+4]), 16, 32)
	return int(v)
}

// parseString reads a JSON string body after the opening quote into code points
// (escaped surrogate pairs combine, as Python's json does).
func parseString() []int {
	var out []int
	for p < len(r) && r[p] != '"' {
		c := int(r[p])
		if c == '\\' {
			e := r[p+1]
			p += 2
			if e == 'u' {
				u := hex4(p)
				p += 4
				if u >= 0xD800 && u <= 0xDBFF && p+5 < len(r) && r[p] == '\\' && r[p+1] == 'u' {
					if v := hex4(p + 2); v >= 0xDC00 && v <= 0xDFFF {
						u = 0x10000 + (u-0xD800)<<10 + (v - 0xDC00)
						p += 6
					}
				}
				out = append(out, u)
			} else {
				v := int(e)
				switch e {
				case 'n':
					v = '\n'
				case 't':
					v = '\t'
				case 'r':
					v = '\r'
				case 'b':
					v = '\b'
				case 'f':
					v = '\f'
				}
				out = append(out, v)
			}
		} else {
			l := 4
			switch {
			case c < 0x80:
				l = 1
			case c < 0xE0:
				l = 2
			case c < 0xF0:
				l = 3
			}
			cp := c
			if l > 1 {
				cp = c & (0xFF >> (l + 1))
			}
			for k := 1; k < l; k++ {
				cp = cp<<6 | int(r[p+k]&0x3F)
			}
			out = append(out, cp)
			p += l
		}
	}
	p++
	return out
}

func nextNumber() int64 {
	for p < len(r) && (r[p] == ',' || r[p] <= ' ') {
		p++
	}
	neg := r[p] == '-'
	if neg {
		p++
	}
	var v int64
	for p < len(r) && r[p] >= '0' && r[p] <= '9' {
		v = v*10 + int64(r[p]-'0')
		p++
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	r, _ = io.ReadAll(os.Stdin)
	for r[p] != '"' {
		p++
	}
	p++
	s := parseString()
	L := int(nextNumber())
	nextNumber() // maxLength: the shortest allowed length is always optimal
	U := int(nextNumber())
	n := len(s)

	// Transitions: global map (state, char) -> edge id, plus per-state edge lists for cloning.
	maxS, maxE := 2*n+2, 3*n+10
	trans := make(map[int64]int32, maxE)
	head := make([]int32, maxS)
	for i := range head {
		head[i] = -1
	}
	enext := make([]int32, 0, maxE)
	ech := make([]int, 0, maxE)
	eto := make([]int32, 0, maxE)
	key := func(st, c int) int64 { return int64(st)<<21 | int64(c) }
	edge := func(st, c int) int32 {
		if e, ok := trans[key(st, c)]; ok {
			return e
		}
		return -1
	}
	addEdge := func(st, c int, to int32) {
		e := int32(len(eto))
		ech = append(ech, c)
		eto = append(eto, to)
		enext = append(enext, head[st])
		head[st] = e
		trans[key(st, c)] = e
	}
	// Suffix automaton; occ counts end positions, first is the end index of the first occurrence.
	link := make([]int, maxS)
	length := make([]int, maxS)
	first := make([]int, maxS)
	occ := make([]int64, maxS)
	link[0], first[0] = -1, -1
	sz, last := 1, 0
	for index, c := range s {
		cur := sz
		sz++
		length[cur], occ[cur], first[cur] = length[last]+1, 1, index
		q := last
		for q >= 0 && edge(q, c) < 0 {
			addEdge(q, c, int32(cur))
			q = link[q]
		}
		if q >= 0 {
			t := int(eto[edge(q, c)])
			if length[q]+1 == length[t] {
				link[cur] = t
			} else {
				clone := sz
				sz++
				length[clone], link[clone], first[clone] = length[q]+1, link[t], first[t]
				for e := head[t]; e >= 0; e = enext[e] {
					addEdge(clone, ech[e], eto[e])
				}
				for q >= 0 {
					e := edge(q, c)
					if int(eto[e]) != t {
						break
					}
					eto[e] = int32(clone)
					q = link[q]
				}
				link[t], link[cur] = clone, clone
			}
		}
		last = cur
	}
	// States by length descending (counting sort), then push counts up suffix links.
	bucket := make([]int, n+2)
	order := make([]int, sz-1)
	for v := 1; v < sz; v++ {
		bucket[length[v]]++
	}
	for l := n - 1; l >= 0; l-- {
		bucket[l] += bucket[l+1]
	}
	for v := 1; v < sz; v++ {
		bucket[length[v]]--
		order[bucket[length[v]]] = v
	}
	for _, v := range order {
		occ[link[v]] += occ[v]
	}

	// valid[i]: the length-L window ending at i has at most U distinct characters.
	cnt := make([]int32, 0x110000)
	valid := make([]bool, n)
	distinct := 0
	for k := 0; k < n; k++ {
		if cnt[s[k]] == 0 {
			distinct++
		}
		cnt[s[k]]++
		if k >= L {
			cnt[s[k-L]]--
			if cnt[s[k-L]] == 0 {
				distinct--
			}
		}
		if k >= L-1 {
			valid[k] = distinct <= U
		}
	}
	var best int64
	for _, v := range order {
		if length[link[v]] < L && L <= length[v] && valid[first[v]] {
			best = max(best, occ[v])
		}
	}
	fmt.Println(best)
}
